create or replace function public.project_sale_attribution(p_sale_id text) returns boolean language plpgsql security definer set search_path=public as $$ declare s record; a record; begin select * into s from public.sales where id=p_sale_id for update; if not found then return false; end if; select * into a from public.attribution_sessions where user_id=s.user_id and funnel_id=s.funnel_id and ((s.click_id is not null and click_id=s.click_id) or (s.click_id is null and session_key is not null and session_key=(s.attribution->>'session_key'))) order by last_seen_at desc nulls last limit 1; if found then update public.sales set attribution=coalesce(s.attribution,'{}'::jsonb)||jsonb_build_object('session_id',a.id,'source',a.source,'medium',a.medium,'campaign',a.campaign,'content',a.content,'term',a.term,'click_id',a.click_id),source=coalesce(s.source,a.source),medium=coalesce(s.medium,a.medium),campaign=coalesce(s.campaign,a.campaign),content=coalesce(s.content,a.content),term=coalesce(s.term,a.term),click_id=coalesce(s.click_id,a.click_id) where id=s.id; end if; return true; end; $$; revoke execute on function public.project_sale_attribution(text) from public,anon,authenticated; grant execute on function public.project_sale_attribution(text) to service_role;